B.WS=new A.cL([B.c2,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
B.WN=new A.cL([B.c1,"Oude Sluis Dubbel","Rozijnen, bruine suiker en een vleugje drop. Een klassieke dubbel zonder poespas.",null,"Emma",4])
B.WT=new A.cL([B.cj,"Stout bij chocolade","De geroosterde tonen van een stout versterken een chocoladedessert. Probeer het eens met een brownie.",null,"BierKompas",null])
B.X3=new A.cL([B.c2,"Gueuze is een blend","Gueuze ontstaat door jonge en oude lambiek te mengen en op fles na te laten gisten. Daardoor krijgt het zijn bruisende, zure karakter.",null,null,null])
B.WP=new A.cL([B.c1,"Veldkers Saison","Droog, peperig en licht fruitig. Elke slok maakt dorst naar de volgende.",null,"Luuk",4.5])
B.X5=new A.cL([B.cj,"Witbier bij vis en mosselen","De citrus- en korianderaroma's van witbier passen perfect bij vis, mosselen en frisse salades.",null,"BierKompas",null])
B.X0=new A.cL([B.c2,"Het Reinheitsgebot","In 1516 bepaalde Beieren dat bier alleen van water, gerst en hop gemaakt mocht worden. Gist werd pas later ontdekt en toegevoegd.",null,null,null])
B.X2=new A.cL([B.c1,"Koperen Nacht Blond","Honingzoet begin en een licht bittere finish. Toegankelijk, maar het mist wat karakter.",null,"Noor",3])
B.WH=new A.cL([B.cj,"Proef van licht naar zwaar","Begin een proeverij met lichte, frisse bieren en werk toe naar zware en zure bieren, zodat je smaakpapillen niet overweldigd raken.",null,"BierKompas",null])
B.WL=new A.cL([B.c2,"Donker is niet sterker","De kleur van bier komt van de mout, niet van het alcoholpercentage. Een donkere stout kan lichter zijn dan een blonde tripel.",null,null,null])
B.WX=new A.cL([B.c1,"Winterlicht Bock","Karamel en geroosterd brood: precies wat je wilt als het buiten stormt.",null,"Milan",4])
B.WO=new A.cL([B.cj,"Ruik voordat je proeft","Een groot deel van wat je proeft is eigenlijk geur. Houd het glas even onder je neus voor de eerste slok.",null,"BierKompas",null])
B.WG=new A.cL([B.c2,"K\xf6lsch is een beschermde naam","Volgens de K\xf6lsch-Konvention mag alleen bier dat in en rond Keulen wordt gebrouwen zich K\xf6lsch noemen.",null,null,null])
B.X8=new A.cL([B.c1,"Havenmeester Pale Ale","Mooi helder, bloemige hop en een droge afdronk. Een echte allrounder.",u.y,"Lotte",4])
B.WU=new A.cL([B.cj,"Kies het juiste glas","Een tulpglas houdt het aroma van speciaalbier vast; een smal pilsglas houdt het koolzuur langer vast.",null,"BierKompas",null])
B.WJ=new A.cL([B.c2,"Witbier kwam terug dankzij een melkboer","Nadat witbier in Belgi\xeb was verdwenen, bracht melkboer Pierre Celis de stijl in 1966 terug in Hoegaarden.",null,null,null])
B.WV=new A.cL([B.c1,"Kelderzuur Kriek","Zuur, kersen en een tikje amandel. Niet voor iedereen, wel voor mij.",null,"Yara",5])
B.WY=new A.cL([B.cj,"Laat de gist in de fles","Bij bieren met nagisting op fles zit gistbezinksel onderin. Schenk rustig en laat het laatste bodempje staan.",null,"BierKompas",null])
B.X1=new A.cL([B.c2,"De kraag doet ertoe","De schuimkraag houdt aroma's vast, zodat je neus meeproeft. Zonder kraag verliest bier sneller zijn geur.",null,null,null])
